add("ex.q2", ("एक अध्ययन से पता चला कि हल्के रंग की आँखों वाले बच्चों के जनक (माता-पिता) की आँखें भी हल्के रंग की होती हैं। इसके आधार पर क्या हम कह सकते हैं कि आँखों के हल्के रंग का लक्षण प्रभावी है अथवा अप्रभावी? अपने उत्तर की व्याख्या कीजिए।",
              "એક અભ્યાસમાં જોવા મળ્યું કે આછા રંગની આંખોવાળાં બાળકોનાં માતા-પિતાની આંખો પણ આછા રંગની હોય છે. તેના આધારે શું આપણે કહી શકીએ કે આંખોના આછા રંગનું લક્ષણ પ્રભાવી છે કે પ્રચ્છન્ન? તમારો જવાબ સમજાવો."),
    {0: ("नहीं।", "ના."), 1: ("बच्चों की आँखों का रंग जनकों जैसा होना लक्षण के प्रभावी या अप्रभावी, दोनों होने पर संभव है; तय करने के लिए ऐसे परिवार चाहिए जहाँ एक प्रकार के जनकों के बच्चे दूसरे प्रकार के हों, और उनकी संख्या भी।",
                         "બાળકોની આંખોનો રંગ માતા-પિતા જેવો હોવો લક્ષણ પ્રભાવી કે પ્રચ્છન્ન બંને હોય ત્યારે શક્ય છે; નક્કી કરવા એવાં કુટુંબો જોઈએ જ્યાં એક પ્રકારનાં માતા-પિતાનાં બાળકો બીજા પ્રકારનાં હોય, અને તેમની સંખ્યા પણ.")})
add("ex.q3", ("कुत्ते की खाल का प्रभावी रंग ज्ञात करने के उद्देश्य से एक प्रोजेक्ट की रूपरेखा बनाइए।", "કૂતરાની ચામડીનો પ્રભાવી રંગ શોધવાના હેતુથી એક પ્રોજેક્ટની રૂપરેખા બનાવો."),
    {0: ("दो खाल-रंगों, जैसे काले और भूरे, के शुद्ध नस्ल वाले कुत्ते चुनिए (जिनके पूर्वजों में कई पीढ़ियों से केवल एक ही रंग रहा हो)।", "બે ચામડીના રંગો, જેમ કે કાળા અને બદામી, ના શુદ્ધ ઓલાદના કૂતરા પસંદ કરો (જેમના પૂર્વજોમાં ઘણી પેઢીઓથી ફક્ત એક જ રંગ રહ્યો હોય)."),
     1: ("काले कुत्ते का भूरे कुत्ते से संकरण कराइए और सभी पिल्लों (F1) का खाल-रंग लिखिए। जो रंग सभी F1 पिल्लों में आए, वह प्रभावी है।", "કાળા કૂતરાનું બદામી કૂતરા સાથે સંકરણ કરાવો અને બધાં ગલૂડિયાં (F1) નો ચામડીનો રંગ નોંધો. જે રંગ બધાં F1 ગલૂડિયાંમાં આવે, તે પ્રભાવી છે."),
     2: ("पुष्टि के लिए F1 कुत्तों का आपस में संकरण कराइए: F2 पिल्लों में लगभग 3 प्रभावी रंग के और 1 अप्रभावी रंग का होना चाहिए।", "પુષ્ટિ માટે F1 કૂતરાઓનું અંદરોઅંદર સંકરણ કરાવો: F2 ગલૂડિયાંમાં લગભગ 3 પ્રભાવી રંગનાં અને 1 પ્રચ્છન્ન રંગનું હોવું જોઈએ.")})
add("ex.q4", ("संतति में नर एवं मादा जनकों द्वारा आनुवंशिक योगदान में बराबर की भागीदारी किस प्रकार सुनिश्चित की जाती है?", "સંતાનમાં નર અને માદા પિતૃઓના જનીનિક યોગદાનમાં સરખી ભાગીદારી કેવી રીતે સુનિશ્ચિત થાય છે?"),
    {0: ("प्रत्येक जनन कोशिका (शुक्राणु या अंड) में हर जोड़े का केवल एक गुणसूत्र, यानी आधा आनुवंशिक पदार्थ, होता है।", "દરેક જનનકોષ (શુક્રકોષ કે અંડકોષ) માં દરેક જોડનું ફક્ત એક રંગસૂત્ર, એટલે કે અડધું જનીનિક દ્રવ્ય, હોય છે."),
     1: ("शुक्राणु और अंड के संलयन पर प्रत्येक जनक एक सेट देता है, इसलिए संतान को दोनों से बराबर आनुवंशिक पदार्थ मिलता है और सामान्य गुणसूत्र संख्या लौट आती है।", "શુક્રકોષ અને અંડકોષના જોડાણથી દરેક પિતૃ એક સમૂહ આપે છે, તેથી સંતાનને બંનેમાંથી સરખું જનીનિક દ્રવ્ય મળે છે અને સામાન્ય રંગસૂત્ર-સંખ્યા પાછી આવે છે.")})

